import pytest

from stats import mean, median, rolling_mean


def test_mean_basic():
    assert mean([1, 2, 3]) == pytest.approx(2.0)


def test_mean_single():
    assert mean([5]) == pytest.approx(5.0)


def test_mean_empty():
    with pytest.raises(ValueError):
        mean([])


def test_median_even_odd():
    assert median([3, 1, 2]) == 2
    assert median([4, 1, 3, 2]) == pytest.approx(2.5)


def test_rolling_mean():
    assert rolling_mean([1, 2, 3, 4], 2) == pytest.approx([1.5, 2.5, 3.5])
    assert rolling_mean([1, 2, 3], 3) == pytest.approx([2.0])
